function binaryTreePaths(root) {
  const parent = new Map([[root, null]]);
  const leaves = [];
  const stack = [root];
  while (stack.length > 0) {                 // one pass: record parents, find leaves
    const node = stack.pop();
    if (node.left === null && node.right === null) leaves.push(node);
    for (const child of [node.right, node.left]) {
      if (child) {
        parent.set(child, node);
        stack.push(child);
      }
    }
  }
  return leaves.map((leaf) => {
    const values = [];
    for (let n = leaf; n !== null; n = parent.get(n)) values.push(n.val);   // climb to the root
    return values.reverse().join("->");
  });
}

public List<String> binaryTreePaths(TreeNode root) {
    Map<TreeNode, TreeNode> parent = new HashMap<>();
    parent.put(root, null);
    List<TreeNode> leaves = new ArrayList<>();
    Deque<TreeNode> stack = new ArrayDeque<>();
    stack.push(root);
    while (!stack.isEmpty()) {              // one pass: record parents, find leaves
        TreeNode node = stack.pop();
        if (node.left == null && node.right == null) leaves.add(node);
        for (TreeNode child : new TreeNode[]{node.right, node.left}) {
            if (child != null) {
                parent.put(child, node);
                stack.push(child);
            }
        }
    }
    List<String> paths = new ArrayList<>();
    for (TreeNode leaf : leaves) {
        LinkedList<String> values = new LinkedList<>();
        for (TreeNode n = leaf; n != null; n = parent.get(n)) values.addFirst(String.valueOf(n.val));   // climb to the root
        paths.add(String.join("->", values));
    }
    return paths;
}

vector<string> binaryTreePaths(TreeNode* root) {
    unordered_map<TreeNode*, TreeNode*> parent{{root, nullptr}};
    vector<TreeNode*> leaves;
    stack<TreeNode*> st;
    st.push(root);
    while (!st.empty()) {                   // one pass: record parents, find leaves
        TreeNode* node = st.top();
        st.pop();
        if (!node->left && !node->right) leaves.push_back(node);
        for (TreeNode* child : {node->right, node->left}) {
            if (child) {
                parent[child] = node;
                st.push(child);
            }
        }
    }
    vector<string> paths;
    for (TreeNode* leaf : leaves) {
        vector<int> values;
        for (TreeNode* n = leaf; n != nullptr; n = parent[n]) values.push_back(n->val);   // climb to the root
        string path;
        for (int i = (int)values.size() - 1; i >= 0; i--) {
            path += to_string(values[i]);
            if (i > 0) path += "->";
        }
        paths.push_back(path);
    }
    return paths;
}

